import json
from pathlib import Path
p=Path('experiments/break-it-down-dag/2026-10-24-graph-first/runs/g08')
urls={'conditional':'https://probabilitycourse.com/chapter1/1_4_0_conditional_probability.php','total':'https://probabilitycourse.com/chapter1/1_4_2_total_probability.php','nb':'https://scikit-learn.org/stable/modules/naive_bayes.html','metrics':'https://developers.google.com/machine-learning/crash-course/classification/accuracy-precision-recall'}
def ev(s,l,c): return {'url':urls[s],'locator':l,'claim':c,'access':'supplied verified source packet'}
def n(i,q,a,status='supported',e=None):return dict(id=i,question=q,answer=a,status=status,evidence=e or [])
nodes=[
n('percent','How do percentages describe a chosen group?','A percentage is a count out of every hundred members of the group named in the statement. Multiplying a group size by its percentage as a decimal gives the corresponding count.','assumed'),
n('conditional','What does a chance given information mean?','Restrict the eligible group to cases consistent with that information, then count what fraction has the property of interest.',e=[ev('conditional','Definition and die example','Conditional probability changes the eligible group and denominator.')]),
n('prior','What is the base rate before the flag is known?','The prior is the share of messages that are spam before observing the flag; the remaining share is legitimate. Here those shares are 1% and 99%.',e=[ev('conditional','Opening rain/cloud example','A prior is the probability before additional information.')]),
n('rates','Which groups do the two flagging rates describe?','90% is the flagged share of actual spam. 10% is the flagged share of legitimate mail. Neither is the spam share of flagged mail.',e=[ev('metrics','Recall; False positive rate; Precision','Recall, false-positive rate, and precision have distinct denominators.')]),
n('counts','How many flags arise from each kind of mail?','Multiply each kind of mail’s size by its own flagging rate; verify the worked counts for 10,000 messages.','gap',[ev('conditional','Chain rule, Equation 1.5','The probability of both events is a group probability times the conditional probability within that group.')]),
n('total','Why must both sources of flags be counted?','Every message is either spam or legitimate. These groups do not overlap, so all flags equal flags from spam plus flags from legitimate mail.',e=[ev('total','Two-event partition formula; Law of Total Probability','Add the weighted contributions of exhaustive, disjoint groups.')]),
n('posterior','What fraction of flags really comes from spam?','Divide spam flags by all flags, using the flagged group as denominator. Verify the result for the supplied numbers.','gap',[ev('conditional','Conditional-probability definition','A conditional probability divides the joint event by the conditioning event.'),ev('metrics','Precision','Precision is true positives divided by all positive predictions.')]),
n('basechange','How does changing the starting spam share change the answer?','Hold both flagging rates fixed, vary the prior, and recompute the weighted contributions. Verify a formula and a few contrasting examples.','gap'),
n('words','How can a word serve as evidence about spam?','Treat observing a word as information. Compare how often it appears within spam with how often it appears within legitimate mail; the more common class is not automatically the one more likely to produce that word.',e=[ev('nb','1.9 opening Bayes theorem','Class evidence is the within-class feature probability, combined with the prior.')]),
n('learn','Where do the word probabilities and prior come from?','Labeled training messages supply class shares and word frequencies. Choose a feature representation: word counts for multinomial models or presence/absence for Bernoulli models.',e=[ev('nb','1.9; 1.9.2 Multinomial; 1.9.4 Bernoulli','Priors and feature parameters are estimated from labeled data using the selected model.')]),
n('independence','When may individual word-clue probabilities be multiplied?','Naive Bayes assumes that, within a fixed class, knowing one feature does not change the probabilities of the others. This is a simplifying model assumption, not a fact about ordinary language.',e=[ev('nb','1.9 conditional independence formula','Conditional independence factors the feature likelihood within each class.')]),
n('scores','How do the prior and several word clues produce a classification?','Multiply each class prior by its model’s joint feature likelihood. Compare the spam and legitimate scores, or divide a score by the sum to obtain its normalized model probability.',e=[ev('nb','1.9 posterior and classification equations','Posterior is proportional to the prior times the conditional feature likelihood.')]),
n('limits','Does the classifier’s numerical probability guarantee real-world reliability?','No. The independence assumption can be inaccurate, and useful classification does not guarantee accurate probability estimates. Actual classifications and their confidence need empirical evaluation.',e=[ev('nb','1.9 final opening paragraph','Naive Bayes can classify well while giving poor probability estimates.'),ev('metrics','Precision; Choice of metric and tradeoffs','Metrics evaluate actual predictions with distinct denominators.')]),
n('target','Why is a flag not almost certainly spam at a 1% base rate, how does the base rate change this, and how do words work as clues?','Pending verified numeric example, base-rate variation, and connection to word evidence.','gap')]
edges=[]
def edge(a,b,w):edges.append(dict(from_=a,to=b,why=w));edges[-1]['from']=edges[-1].pop('from_')
for a,b,w in [
('percent','conditional','Restricting a group is meaningful only once the denominator of its percentage is understood.'),('percent','prior','A starting class share is a percentage of the entire incoming population.'),('conditional','rates','Distinguishing the rates requires recognizing which condition selects the denominator.'),('prior','counts','The starting shares determine how many spam and legitimate cases can generate flags.'),('rates','counts','Each class count must be multiplied by its own within-class flagging rate.'),('counts','total','The total flagged count is formed from the two calculated class contributions.'),('total','posterior','All flags supply the denominator for the spam share among flags.'),('conditional','posterior','The requested reverse question conditions on flags rather than on actual spam.'),('posterior','basechange','Varying prevalence requires recomputing the same posterior calculation.'),('conditional','words','Using a clue requires distinguishing its frequency within a class from the class share among clue-bearing messages.'),('words','learn','Estimating clue probabilities requires specifying what the clue measures.'),('words','independence','Combining clues requires understanding the individual within-class likelihoods.'),('learn','scores','The class and feature estimates supply the numerical score inputs.'),('independence','scores','The simplified joint likelihood needs the conditional-independence assumption.'),('prior','scores','The relative starting class shares weight the evidence likelihoods.'),('scores','limits','Reliability qualifications concern the normalized model scores and resulting classifications.'),('posterior','target','The reversed conditional resolves why 90% detection does not imply 90% trustworthy flags.'),('basechange','target','The question explicitly asks how the answer changes with prevalence.'),('scores','target','The classification rule connects one flag to multiple word clues.'),('limits','target','The word-clue explanation must not imply its normalized scores are guaranteed real frequencies.')]:edge(a,b,w)
g={'title':'Bayesian spam classification: prerequisites and evidence','target':'target','reader_assumptions':['Understands percentages, counts, multiplication, and division.','Has not studied probability or its notation.','Spam and legitimate mail are exhaustive, non-overlapping classes in this exercise.'],'scope':{'include':['Given flagging rates and 1% prevalence','Base-rate variation with rates held fixed','Words as evidence and naive Bayes assumptions'],'exclude':['Current real-world spam prevalence','Full explanation report','Classifier implementation or deployment recommendation']},'nodes':nodes,'edges':edges,'revisions':[]}
snapshot={k:v for k,v in g.items() if k!='revisions'}
g['revisions'].append({'round':0,'stage':'initial_before_supplemental_research','gaps':['Verify expected counts and precision numerically.','Verify base-rate formula and contrasting values.','Read source sections to confirm feature estimation, absence handling, and model-score limitations.'],'searches':[],'evidence':['Supplied bayesian-spam.json packet only.'],'changes':[],'initial_graph':snapshot})
s=json.dumps(g,indent=2,ensure_ascii=False)+'\n'
(p/'dag.json').write_text(s)
(p/'history'/'initial-dag.json').write_text(s)
print('Saved initial dag.json and history/initial-dag.json; 14 nodes, 20 edges.')
